Navigator.push(
context,
MaterialPageRoute(
builder: (context) => const SecondScreen(),
),
);

// Базовый push
Navigator.push(
context,
MaterialPageRoute(
builder: (context) => const DetailScreen(),
),
);

// С настройкой анимации
Navigator.push(
context,
MaterialPageRoute(
builder: (context) => const DetailScreen(),
fullscreenDialog: true, // Полноэкранный диалог (iOS-стиль)
),
);

Navigator.push(
context,
CupertinoPageRoute(
builder: (context) => const IosDetailScreen(),
settings: const RouteSettings(name: '/ios-detail'),
),
);

void main() {
runApp(
MaterialApp(
// Определяем маршруты
routes: {
'/': (context) => const HomeScreen(),
'/about': (context) => const AboutScreen(),
'/settings': (context) => const SettingsScreen(),
'/profile': (context) => const ProfileScreen(),
},
initialRoute: '/',
),
);
}

// Простая навигация по имени
Navigator.pushNamed(context, '/about');

// Навигация с заменой текущего экрана
Navigator.pushReplacementNamed(context, '/settings');

// Навигация с очисткой стека и переходом на начальный экран
Navigator.pushNamedAndRemoveUntil(
context,
'/',
(route) => false, // Удаляем все предыдущие маршруты
);

// Возврат к предыдущему экрану
Navigator.pop(context);

// Закрытие диалога
Navigator.of(context).pop();

MaterialApp(
initialRoute: '/',
onGenerateRoute: (settings) {
switch (settings.name) {
case '/':
return MaterialPageRoute(
builder: (_) => const HomeScreen(),
);
case '/product':
return MaterialPageRoute(
builder: (_) => ProductScreen(
productId: settings.arguments as String,
),
);
default:
return null; // Передать onUnknownRoute
}
},
onUnknownRoute: (settings) {
return MaterialPageRoute(
builder: (_) => const NotFoundScreen(),
);
},
);

// Главный экран приложения
void main() {
runApp(
MaterialApp(
title: 'Navigation Demo',
initialRoute: '/',
routes: {
'/': (context) => const HomeScreen(),
'/details': (context) => const DetailsScreen(),
'/settings': (context) => const SettingsScreen(),
},
),
);
}

// Экран 1: Домашний экран
class HomeScreen extends StatelessWidget {
const HomeScreen({super.key});

@override
Widget build(BuildContext context) {
return Scaffold(
appBar: AppBar(title: const Text('Home')),
body: Center(
child: Column(
mainAxisAlignment: MainAxisAlignment.center,
children: [
ElevatedButton(
onPressed: () {
Navigator.pushNamed(context, '/details');
},
child: const Text('Перейти к деталям'),
),
const SizedBox(height: 16),
ElevatedButton(
onPressed: () {
Navigator.pushNamed(context, '/settings');
},
child: const Text('Настройки'),
),
],
),
),
);
}
}

// Экран 2: Детальный экран
class DetailsScreen extends StatelessWidget {
const DetailsScreen({super.key});

@override
Widget build(BuildContext context) {
return Scaffold(
appBar: AppBar(title: const Text('Details')),
body: Center(
child: ElevatedButton(
onPressed: () {
// Возврат на предыдущий экран
Navigator.pop(context);
},
child: const Text('Назад'),
),
),
);
}
}

// Экран 3: Настройки
class SettingsScreen extends StatelessWidget {
const SettingsScreen({super.key});

@override
Widget build(BuildContext context) {
return Scaffold(
appBar: AppBar(title: const Text('Settings')),
body: Center(
child: ElevatedButton(
onPressed: () {
// Возврат на главный экран с очисткой стека
Navigator.pushNamedAndRemoveUntil(
context,
'/',
(route) => false,
);
},
child: const Text('На главную'),
),
),
);
}
}
